package br.com.onda;
import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;

/** Explicit, local routines. Interpretation never performs an action until Execute is tapped. */
@androidx.media3.common.util.UnstableApi
public class AutomationActivity extends Activity {
 private EditText input;private TextView preview;private Button execute,save;private LinearLayout saved;private String planned="";private LocalAutomation.Plan plan;
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=column();Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,16),Ui.dp(this,8)+i.getSystemWindowInsetTop(),Ui.dp(this,16),Ui.dp(this,8)+i.getSystemWindowInsetBottom());return i;});setContentView(root);
  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.addView(Ui.button(this,"‹",v->finish()),new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));TextView title=Ui.text(this,"Central inteligente",21,Ui.TEXT);Ui.bold(title);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(header);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);LinearLayout body=column();scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  TextView intro=Ui.text(this,"Seu Onda, em um pedido",23,Ui.CYAN);Ui.bold(intro);intro.setPadding(0,Ui.dp(this,12),0,Ui.dp(this,8));body.addView(intro);body.addView(Ui.text(this,"Interpretação local gratuita, por texto ou voz. Confira as etapas antes de executar. Buscas na internet continuam usando conexão; o reconhecimento de voz depende do Android.",13,Ui.MUTED));
  input=new EditText(this);Ui.input(input);input.setSingleLine(false);input.setMinLines(2);input.setMaxLines(4);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(LocalAutomation.MAX_INPUT)});input.setHint("Ex.: toque minhas favoritas em ordem aleatória e pare em 30 minutos");input.setContentDescription("Pedido para a central inteligente");body.addView(input,new LinearLayout.LayoutParams(-1,-2));LinearLayout tools=new LinearLayout(this);Button interpret=Ui.button(this,"Interpretar",v->interpret());interpret.setContentDescription("Interpretar pedido sem executar");Ui.primary(interpret);tools.addView(interpret,new LinearLayout.LayoutParams(0,-2,1));tools.addView(Ui.voiceButton(this,"Ditar pedido para a central inteligente",v->VoiceSearch.start(this,true,"Diga uma rotina ou uma busca para o Onda")),new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));body.addView(tools);
  LinearLayout panel=column();panel.setPadding(Ui.dp(this,14),Ui.dp(this,12),Ui.dp(this,14),Ui.dp(this,12));Ui.playerCard(panel);preview=Ui.text(this,"Seu plano aparecerá aqui. Nenhuma ação é executada ao interpretar.",15,Ui.TEXT);preview.setContentDescription("Etapas da automação");panel.addView(preview);execute=Ui.button(this,"Executar",v->execute());execute.setContentDescription("Executar plano revisado");Ui.primary(execute);panel.addView(execute);save=Ui.button(this,"Salvar rotina",v->saveRoutine());save.setContentDescription("Salvar pedido como rotina local");panel.addView(save);body.addView(panel);invalidatePlan();input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int co,int af){}public void onTextChanged(CharSequence s,int st,int before,int count){invalidatePlan();}public void afterTextChanged(Editable e){}});
  body.addView(Ui.eyebrow(this,"PARA COMEÇAR"));preset(body,"Descansar","toque minhas favoritas; desative o modo aleatório; pare em 30 minutos");preset(body,"Viagem","toque minhas favoritas; ative o modo aleatório");preset(body,"Buscar no YouTube","pesquise Chitãozinho e Xororó no YouTube");preset(body,"Mensagens para compartilhar","imagens de boa noite");saved=column();body.addView(saved);renderSaved();
  body.addView(Ui.button(this,"Personalizar aparência",v->startActivity(new Intent(this,AppearanceActivity.class))));body.addView(Ui.button(this,"Minhas frases de voz",v->startActivity(new Intent(this,VoicePhrasesActivity.class))));Switch enabled=new Switch(this);enabled.setText("IA local nos comandos de voz");enabled.setTextColor(Ui.TEXT);enabled.setMinHeight(Ui.dp(this,48));enabled.setChecked(VoiceAiSettings.enabled(this));enabled.setOnCheckedChangeListener((v,on)->getSharedPreferences("voice_ai",0).edit().putBoolean("local_enabled",on).apply());body.addView(enabled);body.addView(Ui.text(this,"Até seis ações por rotina. Arquivos, conversões, compartilhamento e instalações conservam suas telas e confirmações. Sem IA paga, microfone permanente ou análise contínua em segundo plano.",12,Ui.MUTED));if(state!=null)input.setText(state.getString("draft",""));else if(getIntent().hasExtra("automation_draft")){input.setText(getIntent().getStringExtra("automation_draft"));interpret();}root.setFocusableInTouchMode(true);root.requestFocus();getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);
 }
 private LinearLayout column(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);return box;}
 private void invalidatePlan(){plan=null;planned="";if(execute!=null)execute.setEnabled(false);if(save!=null)save.setEnabled(false);if(preview!=null)preview.setText("Toque em Interpretar para conferir as etapas.");}
 private void interpret(){planned=input.getText().toString().trim();plan=LocalAutomation.parse(planned);preview.setText(plan.summary());execute.setEnabled(plan.valid());save.setEnabled(plan.valid());View focus=getCurrentFocus();if(focus!=null)((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(focus.getWindowToken(),0);}
 private void preset(LinearLayout parent,String label,String phrase){Button b=Ui.button(this,label,v->{input.setText(phrase);interpret();});b.setContentDescription("Preparar rotina "+label);parent.addView(b,new LinearLayout.LayoutParams(-1,-2));}
 private void execute(){if(plan==null||!plan.valid()||!planned.equals(input.getText().toString().trim()))return;execute.setEnabled(false);if(plan.destination==LocalAutomation.Destination.SCREEN){VoiceNavigation.execute(this,plan.commands.get(0));}else if(plan.destination==LocalAutomation.Destination.YOUTUBE||plan.destination==LocalAutomation.Destination.IMAGES){startActivity(new Intent(this,plan.destination==LocalAutomation.Destination.YOUTUBE?YouTubeActivity.class:ImageSearchActivity.class).putExtra("automation_query",plan.query));}else startActivity(new Intent(this,MainActivity.class).putExtra("automation_request",planned).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP));}
 private JSONArray routines(){try{return new JSONArray(getSharedPreferences("automations",0).getString("routines","[]"));}catch(JSONException e){return new JSONArray();}}
 private void saveRoutine(){if(plan==null||!plan.valid())return;String phrase=planned;EditText name=new EditText(this);Ui.input(name);name.setHint("Nome da rotina");name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(40)});AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Salvar rotina neste celular").setView(name).setPositiveButton("Salvar",null).setNegativeButton("Cancelar",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String label=name.getText().toString().trim();if(label.isEmpty()){name.setError("Informe um nome");return;}JSONArray existing=routines(),next=new JSONArray();for(int i=0;i<existing.length();i++){JSONObject item=existing.optJSONObject(i);if(item!=null&&!label.equalsIgnoreCase(item.optString("name")))next.put(item);}if(next.length()>=20){name.setError("Remova uma das 20 rotinas salvas antes de adicionar outra");return;}try{next.put(new JSONObject().put("name",label).put("phrase",phrase));}catch(JSONException e){return;}getSharedPreferences("automations",0).edit().putString("routines",next.toString()).apply();renderSaved();dialog.dismiss();}));dialog.show();}
 private void renderSaved(){saved.removeAllViews();JSONArray routines=routines();if(routines.length()==0)return;saved.addView(Ui.eyebrow(this,"MINHAS ROTINAS"));for(int i=0;i<routines.length();i++){JSONObject item=routines.optJSONObject(i);if(item==null)continue;String label=item.optString("name"),phrase=item.optString("phrase");Button b=Ui.button(this,label,v->{input.setText(phrase);interpret();});b.setContentDescription("Revisar rotina salva "+label);b.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle("Remover rotina?").setMessage(label).setPositiveButton("Remover",(d,w)->{JSONArray old=routines(),next=new JSONArray();for(int n=0;n<old.length();n++){JSONObject row=old.optJSONObject(n);if(row!=null&&!label.equals(row.optString("name")))next.put(row);}getSharedPreferences("automations",0).edit().putString("routines",next.toString()).apply();renderSaved();}).setNegativeButton("Cancelar",null).show();return true;});saved.addView(b);}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==VoiceSearch.REQUEST){String phrase=VoiceSearch.result(result,data);if(!phrase.isEmpty()){input.setText(phrase);interpret();}}}
 @Override protected void onResume(){super.onResume();if(plan!=null)execute.setEnabled(plan.valid());}
 @Override protected void onSaveInstanceState(Bundle state){state.putString("draft",input.getText().toString());super.onSaveInstanceState(state);}
}
